<?php
namespace App\Http\Controllers;
use App\Models\User; use App\Services\AuditService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\Rule;
class UserController extends Controller { public function index(){return view('users.index',['users'=>User::latest()->get()]);} public function create(){return view('users.form',['user'=>new User]);} public function store(Request $r){$d=$r->validate(['name'=>'required|max:100','email'=>'required|email|unique:users,email','role'=>'required|in:admin,kasir','password'=>'required|min:6|confirmed']);$d['password']=Hash::make($d['password']);$user=User::create($d);AuditService::log('user.created',$user,'Akun pengguna ditambahkan');return redirect()->route('users.index')->with('success','Akun berhasil ditambahkan.');} public function edit(User $user){return view('users.form',compact('user'));} public function update(Request $r,User $user){$d=$r->validate(['name'=>'required|max:100','email'=>['required','email',Rule::unique('users','email')->ignore($user)],'role'=>'required|in:admin,kasir','password'=>'nullable|min:6|confirmed']);if(blank($d['password']??null))unset($d['password']);else$d['password']=Hash::make($d['password']);$user->update($d);AuditService::log('user.updated',$user,'Akun pengguna diperbarui');return redirect()->route('users.index')->with('success','Akun berhasil diperbarui.');} }
